 "content": "from collections import deque


def transform(grid):
    """Repeat each colored seed tile across its surrounding zero rectangle."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == 8 or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            cells = []
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 8 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        q.append((nr,nc))

            rs = [r for r, c in cells]
            cs = [c for r, c in cells]
            top, bottom = min(rs), max(rs)
            left, right = min(cs), max(cs)
            colored = [(r,c) for r,c in cells if grid[r][c] not in (0,8)]
            if not colored:
                continue
            crs = [r for r,c in colored]
            ccs = [c for r,c in colored]
            tile_top, tile_left = min(crs), min(ccs)
            tile_h = max(crs) - tile_top + 1
            tile_w = max(ccs) - tile_left + 1
            tile = [
                [grid[tile_top + dr][tile_left + dc] for dc in range(tile_w)]
                for dr in range(tile_h)
            ]

            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    if grid[r][c] != 8:
                        out[r][c] = tile[(r-tile_top) % tile_h][(c-tile_left) % tile_w]

    return out
